import { defineCollection } from 'astro:content';
import { file } from 'astro/loaders';
import { z } from 'astro/zod';

/**
 * One entry per game in `src/content/games.json`.
 *
 * Media is found by convention (see `src/lib/games.ts`):
 *   - src/assets/games/<slug>/thumb.webp      list thumbnail / OG image
 *   - src/assets/games/<slug>/shot-N.webp     screenshots (generated by tools/media-capture)
 *   - public/media/<slug>/clip.{webm,mp4}     short gameplay clip (+ poster.webp)
 * The version comes from apps/<slug>/package.json, and the source link is derived
 * from the repo URL in @games/shared.
 */
const games = defineCollection({
  loader: file('src/content/games.json'),
  schema: z.object({
    title: z.string(),
    tagline: z.string(),
    description: z.string(),
    /** Unpublished games are kept in the data but get no card and no page. */
    published: z.boolean(),
    order: z.number().int(),
    players: z.string(),
    platforms: z.array(z.enum(['desktop', 'mobile'])).min(1),
    engine: z.string().default('Phaser 3'),
    /** Accent colour used for the card glow and buttons of this game. */
    accent: z.string().regex(/^#[0-9a-fA-F]{6}$/),
    /** Width/height of the gameplay clip, used to reserve space. */
    media: z.tuple([z.number().int(), z.number().int()]),
    controls: z.object({
      desktop: z.array(z.string()),
      mobile: z.array(z.string()),
    }),
    features: z.array(z.string()).min(1),
    tags: z.array(z.string()),
  }),
});

export const collections = { games };
